const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-136.325766, 69.954148);

  // Define broader date ranges to increase the chance of finding clear imagery
  const date1_start = '2012-06-10';
  const date1_end = '2012-06-18'; // Centered around June 14

  const date2_start = '2012-07-01';
  const date2_end = '2012-07-09'; // Centered around July 5

  // Turbidity proxy band: For Landsat 7 SR, Band 1 (blue) is a common proxy for water turbidity.
  const turbidityBand = 'B1'; // Blue band

  // Function to mask clouds in Landsat 7 SR imagery
  function maskL7srClouds(image) {
    const qa = image.select('pixel_qa');
    // Bits 0, 1, 2, 3, 4, 5, 6:
    // Bit 0: Fill
    // Bit 1: Dilated Cloud
    // Bit 2: Cirrus (L8 and L9 only, always 0 for L7)
    // Bit 3: Cloud
    // Bit 4: Cloud Shadow
    // Bit 5: Snow/Ice
    // Bit 6: Water (clear)
    // Bit 7: Reserved
    // Bit 8: Clear (high confidence)
    // Bit 9: Low confidence cloud
    // Bit 10: Med confidence cloud
    // Bit 11: High confidence cloud

    // We want to mask out clouds, cloud shadows, snow, and dilated clouds.
    // Clear land (322) and clear water (386) values for pixel_qa indicate good pixels.
    // Values:
    // 322: Clear land
    // 324: Water, low confidence cloud
    // 386: Clear water
    // 388: Water, low confidence cloud
    // Other values indicate clouds, shadows, snow, etc.

    // A simpler approach is to use the 'cloud' and 'cloud shadow' bits.
    // Bit 1: dilated_cloud
    // Bit 3: cloud
    // Bit 4: cloud_shadow
    // Bit 5: snow
    // Bit 6: water

    const cloudMask = qa.bitwiseAnd(1 << 1).eq(0) // Dilated Cloud
      .and(qa.bitwiseAnd(1 << 3).eq(0)) // Cloud
      .and(qa.bitwiseAnd(1 << 4).eq(0)) // Cloud Shadow
      .and(qa.bitwiseAnd(1 << 5).eq(0)); // Snow/Ice

    // Additionally, we are interested in water pixels, Bit 6 should be set to 1 for water.
    const waterMask = qa.bitwiseAnd(1 << 6).neq(0); // water == 1

    return image.updateMask(cloudMask.and(waterMask)).select(turbidityBand).divide(10000); // Scale SR values
  }

  // 2. Data Acquisition & Check
  const l7 = ee.ImageCollection('LANDSAT/LE07/C01/T1_SR');

  let collection1 = l7
    .filterBounds(point)
    .filterDate(date1_start, date1_end)
    .map(maskL7srClouds);

  let collection2 = l7
    .filterBounds(point)
    .filterDate(date2_start, date2_end)
    .map(maskL7srClouds);

  const size1 = await collection1.size().getInfo();
  const size2 = await collection2.size().getInfo();

  console.log(`Period 1 (${date1_start} to ${date1_end}) images: ${size1}`);
  console.log(`Period 2 (${date2_start} to ${date2_end}) images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("Not enough images found in one or both date periods.");
    console.log("C1");
    return;
  }

  // 3. Processing: Reduce the collections to a single image for each period.
  // We'll take the median to reduce noise from individual images.
  const image1 = collection1.median();
  const image2 = collection2.median();

  // 4. Calculation
  // Define scale for reduceRegion (Landsat 7 resolution is 30m, use 30 for accuracy or 100 for speed)
  const scale = 30;

  // Calculate pixel count for image1
  const count1 = await image1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point,
    scale: scale,
    maxPixels: 1e9
  }).get(turbidityBand).getInfo();

  // Calculate turbidity value for image1
  const val1 = await image1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point,
    scale: scale,
    maxPixels: 1e9
  }).get(turbidityBand).getInfo();

  // Calculate pixel count for image2
  const count2 = await image2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point,
    scale: scale,
    maxPixels: 1e9
  }).get(turbidityBand).getInfo();

  // Calculate turbidity value for image2
  const val2 = await image2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point,
    scale: scale,
    maxPixels: 1e9
  }).get(turbidityBand).getInfo();

  console.log(`Period 1 (June) - Turbidity proxy (B1 reflectance): ${val1 !== null ? val1.toFixed(4) : 'N/A'}, Valid Pixels: ${count1}`);
  console.log(`Period 2 (July) - Turbidity proxy (B1 reflectance): ${val2 !== null ? val2.toFixed(4) : 'N/A'}, Valid Pixels: ${count2}`);

  // 5. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels remain after cloud/water masking at the specified location for one or both periods.");
    console.log("C2");
    return;
  }

  if (val1 === null || val2 === null || isNaN(val1) || isNaN(val2)) {
    console.log("Calculation resulted in an invalid value (None/NaN).");
    console.log("C3");
    return;
  }

  // Compare turbidity values
  if (val2 > val1) {
    console.log("A"); // Turbidity increased
  } else {
    console.log("B"); // Turbidity did not increase (decreased or stayed the same)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
